@@ -0,0 +1,27 @@
+// Picks the response language from a request's Accept-Language header.
+import { LANGUAGES } from "../i18n/messages.js";
+
+/** The supported language the Accept-Language `header` prefers (q-values, region tags), else `fallback`. */
+export function pickLanguage(header, fallback) {
+  if (typeof header !== "string") return fallback;
+  const ranges = [];
+  for (const part of header.split(",")) {
+    const [tag, ...params] = part.split(";").map((s) => s.trim().toLowerCase());
+    if (!/^(\*|[a-z]{1,8}(-[a-z0-9]{1,8})*)$/.test(tag)) continue;
+    let q = 1;
+    const weight = params.find((p) => /^q\s*=/.test(p));
+    if (weight !== undefined) {
+      const value = weight.replace(/^q\s*=\s*/, "");
+      if (!/^(0(\.\d{0,3})?|1(\.0{0,3})?)$/.test(value)) continue;
+      q = Number(value);
+    }
+    ranges.push({ lang: tag.split("-")[0], q });
+  }
+  const refused = new Set(ranges.filter((r) => r.q === 0).map((r) => r.lang));
+  const wanted = ranges.filter((r) => r.q > 0).sort((a, b) => b.q - a.q);
+  for (const { lang } of wanted) {
+    if (LANGUAGES.includes(lang)) return lang;
+    if (lang === "*") break;
+  }
+  return [fallback, ...LANGUAGES].find((l) => !refused.has(l)) ?? fallback;
+}
